<?phpnamespace app\api\controller\user;use app\api\controller\Controller;use app\api\model\RechargeLog as RechargeLogModel;/** * 用户交易管理 */class Recharge extends Controller{    /**     * 记录     */    public function logs()    {        $model = new RechargeLogModel;        $list = $model->getList($this->user_id);        return $this->renderSuccess($list);    }}